-- CreateTable
CREATE TABLE "StateVersion" (
    "userId" TEXT NOT NULL,
    "area" TEXT NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 0,
    "changedAt" DATETIME NOT NULL,

    PRIMARY KEY ("userId", "area")
);

-- state-version-triggers (generated by src/lib/mcp/stateAreas.ts)
DROP TRIGGER IF EXISTS "state_Entry_ins";
CREATE TRIGGER "state_Entry_ins" AFTER INSERT ON "Entry"
BEGIN
  INSERT INTO "StateVersion" ("userId", "area", "version", "changedAt")
    SELECT NEW."userId", 'entries', 1, CAST(ROUND((julianday('now') - 2440587.5) * 86400000) AS INTEGER) WHERE NEW."userId" IS NOT NULL
    ON CONFLICT ("userId", "area") DO UPDATE SET "version" = "version" + 1, "changedAt" = excluded."changedAt";
END;
